// t-tests against SciPy (tests/data/ttest-reference.json, regenerated by tests/ttest-reference.py), and the t-test
// page: group order as Stata and R report it, Welch or Student, level() for one command, d_z for paired data.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { gunzipSync } from 'node:zlib';

const page = fs.readFileSync(new URL('../index.html', import.meta.url), 'utf8');
const manifest = JSON.parse(page.match(/<script type="__bundler\/manifest">([\s\S]*?)<\/script>/)[1]);
const E = await import('data:text/javascript;base64,' + gunzipSync(Buffer.from(manifest['7f0c6180-e6c1-4faf-bd4a-6b2fddc15715'].data, 'base64')).toString('base64'));
const template = JSON.parse(page.match(/<script type="__bundler\/template">([\s\S]*?)<\/script>/)[1]);
class Base { props = {}; setState(p, cb) { this.state = { ...this.state, ...(typeof p === 'function' ? p(this.state) : p) }; cb?.(); } forceUpdate() {} }
globalThis.React = { createElement: (tag, props, ...children) => ({ tag, props, children }) }; globalThis.window = { innerWidth: 1440 }; globalThis.document = { documentElement: { style: { zoom: '' } } };
const C = new Function('DCLogic', template.match(/<script type="text\/x-dc"[^>]*>([\s\S]*?)<\/script>/)[1] + ';return Component')(Base);
const parse = async source => { const b = Buffer.from(source); return E.parseCSV(b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength), () => {}); };
const setup = async csv => { const raw = await parse(csv), c = new C(); c._E = E; c._raw = raw; c.jumpArm = () => {}; c.state = { ...c.state, cols: raw.names.map((_, i) => E.profileCol(raw, i)), nRows: raw.n, screen: 'work', tab: 'one', autoScreen: false }; return c; };
const render = (c, patch) => { c.state = { ...c.state, ...patch }; c.clearMemo(); return c.renderVals(); };
const cases = JSON.parse(fs.readFileSync(new URL('./data/ttest-reference.json', import.meta.url), 'utf8'));
const arr = a => a ? Float64Array.from(a, v => v == null ? NaN : v) : null;
const close = (got, want, what, tol = 1e-8) => assert.ok(Math.abs(got - want) <= tol * Math.max(1, Math.abs(want)), what + ': ' + got + ' vs ' + want);

test('one sample, paired, Welch and Student t-tests equal SciPy (estimate, t, df, p, confidence interval)', () => {
  let n = 0;
  for (const [i, c] of cases.entries()) for (const name of ['value', 'paired', 'welch', 'student']) {
    const want = c[name]; if (!want) continue;
    const r = E.ttDetails({ mode: c.mode, x: arr(c.x), y: arr(c.y), mu: c.mu, alpha: c.alpha, equal: name === 'student' });
    assert.ok(!r.error, 'case ' + i + ': ' + r.error);
    const width = Math.abs(want.hi - want.lo);
    for (const k of ['estimate', 't', 'df', 'p']) close(r[k], want[k], 'case ' + i + ' ' + name + ' ' + k);
    for (const k of ['lo', 'hi']) assert.ok(Math.abs(r[k] - want[k]) <= 1e-8 * Math.max(width, Math.abs(want[k]) * 1e-6), 'case ' + i + ' ' + name + ' ' + k + ': ' + r[k] + ' vs ' + want[k]);
    n++;
  }
  assert.ok(n >= 200, n + ' tests compared');
});

test('console: ttest …, by() is Student’s test and …, welch uses Welch’s (1947) degrees of freedom, as Stata prints', async () => {
  for (const c of cases.filter(c => c.mode === 'groups' && c.x.length <= 40)) {
    const rows = ['y,g', ...c.x.map(v => (v ?? '') + ',a'), ...c.y.map(v => (v ?? '') + ',b')].join('\n');
    for (const [cmd, want] of [['ttest y, by(g)', c.student], ['ttest y, by(g) welch', c.welch1947]]) {
      const k = await setup(rows); k.runCmdLine(cmd); clearTimeout(k._mfOkT); assert.equal(k.state.mfCmdErr, '', cmd);
      const tbl = k.state.conLog.at(-1).tbl;
      close(Number(tbl.match(/t =\s+(-?[\d.]+)/)[1]), want.t, cmd + ' t', 1e-4 / Math.max(1, Math.abs(want.t)) + 1e-4);
      close(Number(tbl.match(/Pr\(\|T\| > \|t\|\) = ([\d.]+)/)[1]), want.p, cmd + ' p', 1e-4);
      const df = Number(tbl.match(/degrees of freedom =\s+([\d.]+)/i)[1]); assert.ok(Math.abs(df - want.df) <= 1e-4 * want.df, cmd + ' df ' + df + ' vs ' + want.df);
      if (/welch/.test(cmd)) assert.match(tbl, /Welch's degrees of freedom/);
    }
  }
});

// 40 treated (1) and 20 controls (0): Stata and R report mean(0) - mean(1)
const TREAT = ['score,treat,post', ...Array.from({ length: 60 }, (_, i) => { const t = i < 40 ? 1 : 0; return [50 + 8 * t + ((i * 7) % 11) - 5, t, 52 + 8 * t + ((i * 5) % 9) - 3].join(','); })].join('\n');

test('the page subtracts in Stata’s order (lower code first), can swap, and offers Student’s test', async () => {
  const c = await setup(TREAT);
  let out = render(c, { tab: 'ttest', exploreVar: 'score', ttMode: 'groups', ttG: 'treat' });
  assert.deepEqual(out.stataTtRows.map(r => r.label), ['0', '1', 'Combined', 'diff (first − second)']);
  assert.match(out.ttApa, /^t\(38\.7\) = -9\.18/); assert.match(c._ttLast.tblStata, /diff = mean\(0\) - mean\(1\)\s+t =\s+-9\.1812/); assert.match(c._ttLast.tblStata, /Combined \|\s+60/);
  assert.equal(out.ttSwapLabel, '⇄ Order: 0 minus 1');
  out.ttSwap(); out = c.renderVals(); // as the button does: no cache clearing between renders
  assert.deepEqual(out.stataTtRows.slice(0, 2).map(r => r.label + ' ' + r.n), ['1 40', '0 20'], 'swapped rows carry their own numbers');
  assert.match(c._ttLast.tblStata, /\n       0 \|      20/, 'the console keeps each group with its own numbers');
  assert.match(out.ttApa, /^t\(38\.7\) = 9\.18/); assert.equal(c.ttGroups().flip, true); assert.match(c._ttLast.tblStata, /t =\s+-9\.1812/, 'the console keeps Stata’s order');
  out = render(c, { ttSwap: false, ttEqual: true });
  assert.match(out.ttApa, /^t\(58\) = /); assert.equal(c._ttLast.stata, 'ttest score, by(treat)'); assert.match(c._ttLast.r, /var\.equal = TRUE/);
  assert.match(c._ttLast.tblStata, /^Two-sample t test with equal variances/); assert.match(c._ttLast.tblStata, /Degrees of freedom =\s+58/); assert.match(c._ttLast.tblR, /^\n\t Two Sample t-test/);
  out = render(c, { ttEqual: false }); assert.equal(c._ttLast.stata, 'ttest score, by(treat) unequal');
});

test('level() applies to that command only; paired effect size is d_z', async () => {
  const c = await setup(TREAT);
  c.runCmdLine('ttest score == 52, level(90)'); clearTimeout(c._mfOkT); assert.equal(c.state.mfCmdErr, '');
  assert.equal(c.alpha(), 0.1); let out = render(c, {}); assert.equal(out.stataTtCI, '90% conf. interval'); assert.equal(c._ttLast.stata, 'ttest score == 52, level(90)');
  c.runCmdLine('summarize score'); clearTimeout(c._mfOkT); assert.equal(c.alpha(), 0.05, 'the next command is back at 95%');
  c.runCmdLine('ttest score, by(treat) unequal level(99)'); clearTimeout(c._mfOkT); out = render(c, {}); assert.equal(out.stataTtCI, '99% conf. interval');
  c.runCmdLine('ttest score == 52, level(150)'); clearTimeout(c._mfOkT); assert.match(c.state.mfCmdErr, /between 10 and 99\.99/);
  out = render(c, { tab: 'ttest', exploreVar: 'score', ttMode: 'paired', ttY2: 'post', alphaSel: '' });
  assert.ok(out.ttCells.some(x => x.k === "COHEN'S D_Z")); assert.match(out.ttApa, /d_z = /);
});
